import {webcrypto} from 'crypto';
import {TextEncoder} from 'util';

import {CasinoBet, VideoPokerCategory} from 'types/casino';

import {
  evaluateVideoPokerHand,
  verifyVideoPokerReceipt,
  VIDEO_POKER_PAY_TABLE,
  videoPokerMultiplier,
} from './videoPokerFairness';

const hash = '60e05bd1b195af2f94112fa7197a5c88289058840ce7c6df9693756bc6250f55';
// Fixed vectors generated by the backend engine from the published deck order and HMAC algorithm.
const vectors: {
  action: string;
  category: VideoPokerCategory;
  dealt: string[];
  hand: string[];
  multiplier: number;
  name: string;
  seed: string;
}[] = [
  {
    name: 'two pair after replacing two cards',
    seed: 'vector-1',
    action: 'draw:10110',
    dealt: ['3D', '2S', '9D', '3S', 'QC'],
    hand: ['3D', '9S', '9D', '3S', 'QD'],
    category: 'two_pair',
    multiplier: 2,
  },
  {
    name: 'a flush drawn to two held diamonds',
    seed: 'test-client',
    action: 'draw:10010',
    dealt: ['8D', '9H', '6H', 'AD', '10S'],
    hand: ['8D', '3D', 'JD', 'AD', 'QD'],
    category: 'flush',
    multiplier: 6,
  },
  {
    name: 'a pair of kings returning the wager',
    seed: 'vector-0',
    action: 'draw:10000',
    dealt: ['KS', '2D', '6H', '10S', '7D'],
    hand: ['KS', '7H', 'KC', '4S', '6C'],
    category: 'jacks_or_better',
    multiplier: 1,
  },
  {
    name: 'a straight filled from both ends',
    seed: 'vector-3',
    action: 'draw:01011',
    dealt: ['9D', '6C', '3C', '5D', '3S'],
    hand: ['2D', '6C', '4H', '5D', '3S'],
    category: 'straight',
    multiplier: 4,
  },
  {
    name: 'three of a kind',
    seed: 'vector-6',
    action: 'draw:01001',
    dealt: ['3S', '4C', '7D', '3C', '4S'],
    hand: ['5C', '4C', '3H', '4D', '4S'],
    category: 'three_of_a_kind',
    multiplier: 3,
  },
  {
    name: 'a full house',
    seed: 'vector-11',
    action: 'draw:01001',
    dealt: ['8D', '8S', '6C', 'AS', '8C'],
    hand: ['KC', '8S', 'KH', 'KS', '8C'],
    category: 'full_house',
    multiplier: 9,
  },
  {
    name: 'four of a kind from five new cards',
    seed: 'vector-50',
    action: 'draw:00000',
    dealt: ['10H', 'JD', '2H', '8H', 'AH'],
    hand: ['4C', '4D', '4S', 'AC', '4H'],
    category: 'four_of_a_kind',
    multiplier: 25,
  },
  {
    name: 'a straight flush',
    seed: 'vector-237',
    action: 'draw:00101',
    dealt: ['QC', '9H', '6C', '7S', '7C'],
    hand: ['3C', '4C', '6C', '5C', '7C'],
    category: 'straight_flush',
    multiplier: 50,
  },
  {
    name: 'a losing hand kept exactly as dealt',
    seed: 'vector-2',
    action: 'draw:11111',
    dealt: ['10D', 'KC', '9C', '10C', '5D'],
    hand: ['10D', 'KC', '9C', '10C', '5D'],
    category: 'nothing',
    multiplier: 0,
  },
  {
    name: 'a losing hand after discarding everything',
    seed: 'vector-2',
    action: 'draw:00000',
    dealt: ['10D', 'KC', '9C', '10C', '5D'],
    hand: ['8D', 'QD', '5H', '9S', '10H'],
    category: 'nothing',
    multiplier: 0,
  },
];

const makeBet = (vector = vectors[0]): CasinoBet => {
  const amount = 4;
  const payout = vector.multiplier * amount;
  return {
    amount,
    created_at: '2026-11-25T12:00:00Z',
    fund: {available: 100000, balance: 100000, currency: 'TNB', enabled: true, reserved: 0, risk_limit_bps: 100},
    game: 'video_poker',
    id: 1,
    payout,
    profit: payout - amount,
    request_id: '00000000-0000-0000-0000-000000000002',
    rules_version: 1,
    settled_at: '2026-11-25T12:01:00Z',
    status: 'settled',
    total_stake: amount,
    wallet_balance: 1000 - amount + payout,
    fairness: {
      algorithm: 'hmac-sha256-v1',
      client_seed: vector.seed,
      commitment_id: '00000000-0000-0000-0000-000000000001',
      server_seed: '00'.repeat(32),
      server_seed_hash: hash,
    },
    result: {
      actions: [vector.action],
      available_actions: [],
      category: vector.category,
      dealt: vector.dealt,
      expires_at: null,
      hand: vector.hand,
      held: vector.action
        .slice(5)
        .split('')
        .map((flag) => flag === '1'),
      multiplier: vector.multiplier,
      phase: 'settled',
      revision: 1,
    },
  };
};

beforeAll(() => {
  Object.defineProperty(globalThis, 'crypto', {configurable: true, value: webcrypto});
  Object.defineProperty(globalThis, 'TextEncoder', {configurable: true, value: TextEncoder});
});

it.each(vectors)('replays $name from an independent deterministic vector', async (vector) => {
  await expect(verifyVideoPokerReceipt(makeBet(vector), hash)).resolves.toContain('pre-bet commitment');
});

it('distinguishes history verification from a locally observed pre-bet commitment', async () => {
  await expect(verifyVideoPokerReceipt(makeBet())).resolves.toContain('not saved on this device');
  await expect(verifyVideoPokerReceipt(makeBet(), 'ff'.repeat(32))).rejects.toThrow('committed hash');
});

it('rejects an altered revealed seed and unsupported rules', async () => {
  const bet = makeBet();
  await expect(
    verifyVideoPokerReceipt({...bet, fairness: {...bet.fairness, server_seed: '11'.repeat(32)}}, hash),
  ).rejects.toThrow('committed hash');
  await expect(verifyVideoPokerReceipt({...bet, rules_version: 2}, hash)).rejects.toThrow('unsupported rules');
  await expect(verifyVideoPokerReceipt({...bet, status: 'open'}, hash)).rejects.toThrow('not settled');
  await expect(verifyVideoPokerReceipt({...bet, game: 'blackjack'}, hash)).rejects.toThrow('unsupported rules');
});

it('rejects changed cards, holds, categories, and multipliers', async () => {
  const bet = makeBet(vectors[1]);
  const changes = [
    {dealt: ['8D', '9H', '6H', 'AD', 'JS']},
    {hand: ['8D', '3D', 'JD', 'AD', 'KD']},
    {held: [true, false, false, true, true]},
    {category: 'straight_flush' as const},
    {multiplier: 50},
    {revision: 2},
    {actions: ['draw:10011']},
  ];
  for (const change of changes) {
    // eslint-disable-next-line no-await-in-loop
    await expect(verifyVideoPokerReceipt({...bet, result: {...bet.result, ...change}}, hash)).rejects.toThrow(
      'does not match the committed cards',
    );
  }
});

it('checks stake, payout, and profit independently', async () => {
  const bet = makeBet(vectors[1]);
  await expect(verifyVideoPokerReceipt({...bet, total_stake: 8}, hash)).rejects.toThrow('payout');
  await expect(verifyVideoPokerReceipt({...bet, payout: 25}, hash)).rejects.toThrow('payout');
  await expect(verifyVideoPokerReceipt({...bet, profit: 24}, hash)).rejects.toThrow('payout');
});

it('rejects invalid wagers and a missing or malformed record of the holds before replaying', async () => {
  const bet = makeBet();
  await expect(verifyVideoPokerReceipt({...bet, amount: 0}, hash)).rejects.toThrow('invalid Video Poker wager');
  await expect(verifyVideoPokerReceipt({...bet, amount: 1.5}, hash)).rejects.toThrow('invalid Video Poker wager');
  for (const actions of [undefined, [], ['draw:1011'], ['hold:10110'], ['draw:10110', 'draw:11111']]) {
    // eslint-disable-next-line no-await-in-loop
    await expect(verifyVideoPokerReceipt({...bet, result: {...bet.result, actions}}, hash)).rejects.toThrow(
      'cards that were held',
    );
  }
});

it.each([
  [['10S', 'JS', 'QS', 'KS', 'AS'], 'royal_flush'],
  [['9S', '10S', 'JS', 'QS', 'KS'], 'straight_flush'],
  [['AD', '2D', '3D', '4D', '5D'], 'straight_flush'],
  [['7C', '7D', '7H', '7S', 'AC'], 'four_of_a_kind'],
  [['2C', '2D', 'KH', 'KS', 'KC'], 'full_house'],
  [['JC', 'QC', 'KC', 'AC', '2C'], 'flush'],
  [['AC', '2D', '3H', '4S', '5C'], 'straight'],
  [['10C', 'JD', 'QH', 'KS', 'AC'], 'straight'],
  [['QC', 'KD', 'AH', '2S', '3C'], 'nothing'],
  [['4C', '4D', '4H', '9S', 'KC'], 'three_of_a_kind'],
  [['4C', '4D', '9H', '9S', 'KC'], 'two_pair'],
  [['JC', 'JD', '3H', '8S', 'KC'], 'jacks_or_better'],
  [['AC', 'AD', '3H', '8S', '2C'], 'jacks_or_better'],
  [['10C', '10D', '3H', '8S', 'AC'], 'nothing'],
  [['2C', '5D', '9H', 'JS', 'AC'], 'nothing'],
] as [string[], VideoPokerCategory][])('evaluates %j as %s', (cards, category) => {
  expect(evaluateVideoPokerHand(cards)).toBe(category);
  expect(evaluateVideoPokerHand([...cards].reverse())).toBe(category);
});

it('rejects malformed hands and publishes the 9/6 pay table', () => {
  expect(() => evaluateVideoPokerHand(['AS', 'AS', 'KS', 'QS', 'JS'])).toThrow('five different cards');
  expect(() => evaluateVideoPokerHand(['AS', 'KS', 'QS', 'JS'])).toThrow('five different cards');
  expect(() => evaluateVideoPokerHand(['AS', 'KS', 'QS', 'JS', '1X'])).toThrow('unknown card');
  expect(VIDEO_POKER_PAY_TABLE.map((row) => row.multiplier)).toEqual([250, 50, 25, 9, 6, 4, 3, 2, 1]);
  expect(videoPokerMultiplier('full_house')).toBe(9);
  expect(videoPokerMultiplier('nothing')).toBe(0);
});
